static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than 0");
        }

        int year = (int) (timeBucket / 10000);
        int dayOfYear = (int) (timeBucket % 10000);

        // Calculate the number of days to subtract
        int daysToSubtract = (dayOfYear - 1) % dayStep;

        // Calculate the new day of the year
        int newDayOfYear = dayOfYear - daysToSubtract;

        // Format the new time bucket
        long newTimeBucket = ((long) year * 10000) + newDayOfYear;

        return newTimeBucket;
    } catch (Exception e) {
        // Handle any exceptions that may occur
        System.err.println("Error compressing time bucket: " + e.getMessage());
        return timeBucket; // Return the original time bucket in case of error
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid index or length");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // surrogate pair
                i++; // skip the low surrogate
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

