private static LinkedBuffer ensureCapacity(int required, LinkedBuffer lb, WriteSession session) {
    if (lb.offset + required > lb.limit) {
        lb = lb.next;
        if (lb == null) {
            lb = session.nextBuffer();
        }
    }
    return lb;
}

