public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    float minX = box.getMinX();
    float minY = box.getMinY();
    float maxX = box.getMaxX();
    float maxY = box.getMaxY();

    if (minX >= maxX) {
        throw new IllegalArgumentException("Invalid box dimensions");
    }

    float midX = minX + (maxX - minX) / 2.0f;

    Box2D leftBox = new Box2D(minX, minY, midX, maxY);
    Box2D rightBox = new Box2D(midX, minY, maxX, maxY);

    return new Pair<>(leftBox, rightBox);
}

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (size == 0) {
        return; // No need to enlarge if no additional bytes are required
    }
    int currentCapacity = (this.data == null) ? 0 : this.data.length;
    int requiredCapacity = currentCapacity + size;
    byte[] newData = new byte[requiredCapacity];
    if (this.data != null) {
        System.arraycopy(this.data, 0, newData, 0, currentCapacity);
    }
    this.data = newData;
}

