void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream cannot be null");
    }
    try {
        byte[] buffer = new byte[in.available()];
        int bytesRead = in.read(buffer);
        while (bytesRead != -1) {
            // If the buffer is full, create a new one with double the size
            if (buffer.length == bytesRead) {
                byte[] newBuffer = new byte[buffer.length * 2];
                System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
                buffer = newBuffer;
            }
            bytesRead = in.read(buffer, bytesRead, buffer.length - bytesRead);
        }
        // Trim the buffer to the actual number of bytes read
        this.buffer = Arrays.copyOf(buffer, bytesRead);
        this.readPointer = 0;
    } catch (IOException e) {
        throw new IOException("Error reading from InputStream", e);
    } finally {
        in.close();
    }
}

