        if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
            throw new IndexOutOfBoundsException("constantPoolEntryIndex is out of bounds");
        }

        if (charBuffer == null) {
            throw new IllegalArgumentException("charBuffer cannot be null");
        }

        // Read the length of the UTF8 string
        int utfLength = (classFileBuffer[constantPoolEntryIndex] & 0xFF) << 8 |
                        (classFileBuffer[constantPoolEntryIndex + 1] & 0xFF);

        int index = constantPoolEntryIndex + 2;
        int charIndex = 0;

        for (int i = 0; i < utfLength; ) {
            int c = classFileBuffer[index++] & 0xFF;
            switch (c >> 4) {
                case 0: case 1: case 2: case 3: case 4: case 5: case 6: case 7:
                    // 0xxxxxxx
                    charBuffer[charIndex++] = (char) c;
                    i++;
                    break;
                case 12: case 13:
                    // 110xxxxx 10xxxxxx
                    charBuffer[charIndex++] = (char) (((c & 0x1F) << 6) |
                                                       (classFileBuffer[index++] & 0x3F));
                    i += 2;
                    break;
                case 14:
                    // 1110xxxx 10xxxxxx 10xxxxxx
                    charBuffer[charIndex++] = (char) (((c & 0x0F) << 12) |
                                                       ((classFileBuffer[index] & 0x3F) << 6) |
                                                       (classFileBuffer[index + 1] & 0x3F));
                    index += 2;
                    i += 3;
                    break;
                default:
                    throw new IllegalArgumentException("malformed input: invalid UTF-8 sequence");
            }
        }

