protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour must contain at least one edge");
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    try {
        for (E edge : edgeList) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            if (vertexList.get(vertexList.size() - 1).equals(source)) {
                vertexList.add(target);
            } else if (vertexList.get(vertexList.size() - 1).equals(target)) {
                vertexList.add(source);
            } else {
                throw new IllegalArgumentException("Edges do not form a valid path");
            }
        }
    } catch (IllegalArgumentException e) {
        throw e;
    } catch (Exception e) {
        throw new RuntimeException("An error occurred while constructing the path", e);
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList.get(vertexList.size() - 1), edgeList, graph.getType().isDirected());
}

