public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("StringBuffer cannot be null");
    }
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("nameStart index is out of bounds");
    }

    // Extract the substring starting from nameStart
    String name = buf.substring(nameStart);

    // Split the name by spaces or hyphens to get parts
    String[] parts = name.split("[\\s-]+");

    // If there are more than one parts, take the first character of each part except the last
    if (parts.length > 1) {
        StringBuilder abbreviation = new StringBuilder();
        for (int i = 0; i < parts.length - 1; i++) {
            if (!parts[i].isEmpty()) {
                abbreviation.append(parts[i].charAt(0));
            }
        }
        // Append the last part in full
        abbreviation.append(parts[parts.length - 1]);

        // Replace the original part in the buffer with the abbreviation
        buf.replace(nameStart, buf.length(), abbreviation.toString());
    }
}

