private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    try {
        // Check if the descriptor is a method descriptor
        if (descriptor.startsWith("(")) {
            int endIndex = descriptor.indexOf(')');
            if (endIndex == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }
            String argumentTypes = descriptor.substring(1, endIndex);
            int index = 0;
            while (index < argumentTypes.length()) {
                char c = argumentTypes.charAt(index);
                switch (c) {
                    case 'B': // byte
                    case 'C': // char
                    case 'D': // double
                    case 'F': // float
                    case 'I': // int
                    case 'S': // short
                    case 'Z': // boolean
                        index++;
                        break;
                    case 'J': // long
                        index += 2;
                        break;
                    case 'L': // class
                    case '[': // array
                        index = argumentTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid class or array descriptor");
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character in descriptor: " + c);
                }
                // Pop the type from the output frame stack
                // Assuming there's a method to pop a type from the stack
                popTypeFromStack();
            }
        } else {
            // Handle the descriptor as a single type descriptor
            switch (descriptor.charAt(0)) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                    popTypeFromStack();
                    break;
                case 'J': // long
                    popTypeFromStack();
                    popTypeFromStack(); // longs take two slots
                    break;
                case 'L': // class
                case '[': // array
                    popTypeFromStack();
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type descriptor: " + descriptor);
            }
        }
    } catch (StringIndexOutOfBoundsException | IllegalArgumentException e) {
        throw new IllegalArgumentException("Malformed descriptor: " + descriptor, e);
    }
}

